solution.solution.cpp:
#include <sstream>
#include <string>
#include <vector>

struct Section { std::string type; std::string name; std::vector<std::string> lines; };

std::vector<Section> readIni(const std::string& text)
{
    std::vector<Section> out;
    std::istringstream in{ text };
    std::string line;
    while (std::getline(in, line))
    {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.size() >= 4 && line[0] == '[')
        {
            const auto close{ line.find(']') };
            const auto last{ line.rfind(']') };
            if (close != std::string::npos && close + 1 < line.size() && line[close + 1] == '[' && last > close + 1)
            {
                out.push_back({ line.substr(1, close - 1), line.substr(close + 2, last - close - 2), {} });
                continue;
            }
        }
        if (line.empty() || out.empty()) continue;
        out.back().lines.push_back(line);
    }
    return out;
}

std::string writeIni(const std::vector<Section>& sections)
{
    std::string out;
    for (const Section& s : sections)
    {
        out += "[" + s.type + "][" + s.name + "]\n";
        for (const std::string& l : s.lines) out += l + "\n";
        out += "\n";
    }
    return out;
}

std::string getValue(const Section& s, const std::string& key)
{
    const std::string prefix{ key + "=" };
    for (const std::string& l : s.lines) if (l.rfind(prefix, 0) == 0) return l.substr(prefix.size());
    return "";
}

void setValue(Section& s, const std::string& key, const std::string& value)
{
    const std::string prefix{ key + "=" };
    for (std::string& l : s.lines) if (l.rfind(prefix, 0) == 0) { l = prefix + value; return; }
    s.lines.push_back(prefix + value);
}

unitTests:
const std::string sample = "; written by hand
[Window][Stones]
Pos=60,40
Size=320,260

[Table][0x8A4C2B11,4]
Column 0  Weight=1.0000

[Docking][Data]
DockSpace ID=0x3BC79352
  DockNode ID=0x00000001
";
TEST("sections") {
    const auto s = readIni(sample);
    CHECK_EQ(s.size(), std::size_t{ 3 });
    CHECK_EQ(s[0].type, std::string("Window")); CHECK_EQ(s[0].name, std::string("Stones")); CHECK_EQ(s[0].lines.size(), std::size_t{ 2 });
    CHECK_EQ(s[1].type, std::string("Table")); CHECK_EQ(s[1].name, std::string("0x8A4C2B11,4"));
    CHECK_EQ(s[2].lines, (std::vector<std::string>{ "DockSpace ID=0x3BC79352", "  DockNode ID=0x00000001" }));
}
TEST("values") { auto s = readIni(sample); CHECK_EQ(getValue(s[0], "Size"), std::string("320,260")); CHECK_EQ(getValue(s[0], "Collapsed"), std::string("")); setValue(s[0], "Size", "400,300"); setValue(s[0], "Collapsed", "1"); CHECK_EQ(s[0].lines, (std::vector<std::string>{ "Pos=60,40", "Size=400,300", "Collapsed=1" })); }
TEST("write") { const auto s = readIni("[A][b]
x=1
[C][d]
"); CHECK_EQ(writeIni(s), std::string("[A][b]
x=1

[C][d]

")); }
TEST("round trip keeps unknown sections") { const auto s = readIni(sample); const auto again = readIni(writeIni(s)); CHECK_EQ(again.size(), s.size()); CHECK_EQ(again[2].lines, s[2].lines); CHECK_EQ(again[1].name, s[1].name); }
TEST("empty") { CHECK(readIni("").empty()); CHECK_EQ(writeIni({}), std::string("")); }

